function wfMode(p){return wfGet(p).mode||'hotspot'}
function wfCanTask(p){const missing=[];if(!p?.title?.trim())missing.push('作品名称');if(wfMode(p)==='hotspot'&&!validSources(p).length)missing.push('至少一条可信事件来源链接');if(wfMode(p)==='hotspot'&&!p.factNotes?.trim())missing.push('事实核验记录');if(!p.fiction?.trim())missing.push('脱敏与虚构改编方案');return missing}
function wfTaskObject(p){const h=wfGet(p);return {schema:WF_SCHEMA,task_id:h.taskId,created_at:h.taskAt,producer:'ChatGPT',publisher:'WorkBuddy',brand:'WORLD/TOON · By DAVYLAB',title:p.title,subtitle:p.subtitle,category:p.category,mode:wfMode(p),creative_tone:p.tone||'克制讽刺',format:'九格原创漫画',source:{headline:p.sourceTitle,urls:validSources(p),date:p.eventDate,verified_facts:p.factNotes||'原创虚构故事'},adaptation:{strategy:p.fiction,characters:p.characters,disclaimer:p.disclosure},story:p.description,panels:p.panels.map((x,i)=>({index:i+1,title:x.title,scene:x.scene,caption:x.caption,dialogue:x.dialogue,visual_notes:x.prompt})),requirements:{panel_count:9,independent_images:true,cover_required:true,language:'zh-CN',visual_style:'国际高端杂志式漫画：高级分镜、克制配色、原创人物、统一角色设定，禁止通用霓虹 AI 模板',art:'九张独立竖版 PNG/JPEG/WebP 漫画图 + 独立封面，文字准确可读；如生图文字难以保证则以独立文本图层排版',delivery_zip:'chatgpt-delivery.zip',paths:['delivery.json','cover.png','panels/01.png ... panels/09.png','comic.pdf (可选)','weixin-caption.txt (可选)'],public_claims:'未经证实的指控、婚恋隐私、违法或交易传闻不得描绘成真实事实；人物不可仅换名仍可被识别'}}}
function wfPrompt(p){const o=wfTaskObject(p);return `你是 WORLD/TOON · By DAVYLAB 的专属漫画编剧、美术总监、质量审校。\n本任务由我的漫画平台正式下发，ChatGPT 负责完成整部漫画生产，WorkBuddy 负责随后在微信公众号发布。\n\n任务编号：${o.task_id}\n标题：《${p.title}》\n题材：${p.category} · ${wfMode(p)==='original'?'完全虚构':'全球热点虚构改编'}\n创作风格：${p.tone||'高级杂志感、黑色幽默'}。必须使用统一角色形象和美术风格。\n现实事件链接：${validSources(p).join('；')||'完全虚构，无特定现实事件'}\n已核验信息：${p.factNotes||'完全虚构'}\n虚构改编原则：${p.fiction}\n角色设定：${p.characters||'请创作原创虚构角色'}\n剧情：${p.description||'请基于选题完善'}\n说明：${p.disclosure}\n\n请按以下要求完成，不只输出方案：\n1. 核查新闻事件与原始来源，区分事实、传闻、观点；无法核验的内容不要成为针对真实个人的影射指控。不得把“改名/匿名”当作唯一脱敏。\n2. 完成 9 格分镜台词，并生成 9 张彼此独立的漫画图片，画幅适合手机贴图阅读（建议 3:4）；角色、服装、视觉系统贯穿全书；不要只提供一张九宫格拼图。\n3. 同时生成独立封面、准确的中文台词、故事导语和微信贴图文案；如有可用的 PDF 漫画册也一并生成。\n4. 输出正式交付 ZIP，内容结构：delivery.json、cover.png、panels/01.png 到 panels/09.png、comic.pdf（可选）、weixin-caption.txt（可选）；不使用占位图片。可以提供 JPG/WebP，但对应文件名需清楚编号。\n5. delivery.json 至少包含 {"schema":"davylab.worldtoon.delivery.v1","task_id":"${o.task_id}","title":"${p.title}","panel_count":9,"disclaimer":"${(p.disclosure||'原创虚构漫画').replace(/"/g,'“')}","qa":{"panels_verified":true,"characters_consistent":true,"text_reviewed":true,"sources_checked":true}}。\n6. 在输出中列出版权与事实核验注意事项；未完成/未检查的项目必须如实说明，不得虚报已生成和已发表。\n\n已拟定分镜（允许优化叙事，不得虚构现实指控）：\n${p.panels.map((a,i)=>`#${String(i+1).padStart(2,'0')} ${a.title||'第'+(i+1)+'格'}\n画面：${a.scene||'待设计'}\n旁白：${a.caption||'待撰写'}\n对白：${a.dialogue||'待撰写'}\n美术备注：${a.prompt||'无'}`).join('\n\n')}\n\n完成后请直接交付下载文件。正式交付要求：将九张真实独立图片、封面、来源和文案以二进制提交到私有 GitHub 仓库 chenzhe223-tech/worldtoon 的 deliveries/<task_id>/；最后才设置 ready_for_qa=true。不得以 sandbox 链接或 ZIP 文件名称冒充 GitHub 交付。GitHub Actions 严格验收后形成 queue/workbuddy.json；WorkBuddy 定时扫描并发表，最后写入 receipts/<task_id>.json。`}
function wfHint(){return `<div class="wf-banner"><strong>制作流程已调整：</strong>本站负责选题、核验与任务工单，ChatGPT 负责生成漫画，WorkBuddy 负责公众号贴图发表。本站不调用自动生图接口。 <a href="#/handoff"><strong>进入制作交接中心 →</strong></a></div>`}
function wtWorkflow(){const ps=activeProjects(),p=selected();const h=wfGet(p);return heroHeader('THE PRODUCTION DESK / THREE-HANDOFFS','制作交接中心','平台建单 → ChatGPT 生产漫画交付包 → WorkBuddy 公众号贴图发表。GitHub 是正式派单及交付中心：任务必须真实入仓，作品必须通过审核，公众号必须有真实回执才算发表。')+
'<div class="wf-path"><span>01 平台：选题与制作任务</span><span>→</span><span>02 ChatGPT：九格漫画交付</span><span>→</span><span>03 WorkBuddy：微信公众号发表</span></div>'+
`<div class="box"><div class="wf-form"><div class="field"><label>选择项目</label><select id="wfProject">${ps.map(x=>`<option value="${e(x.id)}" ${p?.id===x.id?'selected':''}>${e(x.title)}</option>`).join('')}</select></div><div class="field"><label>内容类别</label><select id="wfMode"><option value="hotspot" ${wfMode(p)==='hotspot'?'selected':''}>全球热点虚构改编</option><option value="original" ${wfMode(p)==='original'?'selected':''}>完全原创虚构</option></select></div><div>${wfStatus(p)}</div></div><p class="wf-meta">资料编辑请到 <a href="#/studio/${e(p?.id||'')}">创作工作台</a> · 素材来源请到 <a href="#/radar">选题池</a> · 图片回传只保存在当前作品，不会替换其他项目</p></div>`+
(p?`<div class="wf-layout"><section class="wf-step ${wfPhase(p)==='not_started'?'active':''}"><div class="wf-stephead"><span class="wf-num">01</span><span class="chip">平台</span></div><h3>生成制作任务</h3><p>整理新闻来源、事实与虚构边界、角色设定、九格分镜，产生可追溯的任务编号和标准任务包。</p><p class="wf-meta">${h.taskId?'任务编号：'+e(h.taskId):'尚未建立任务'}</p>${wfCanTask(p).length?`<p class="risk">先补全：${e(wfCanTask(p).join('、'))}</p>`:''}<button class="button dark" data-wf="task">生成 ChatGPT 任务 ZIP</button><button class="button" data-wf="copy">复制制作指令</button><a class="button" href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">打开 ChatGPT ↗</a></section>
<section class="wf-step ${wfPhase(p)==='task_ready'?'active':''}"><div class="wf-stephead"><span class="wf-num">02</span><span class="chip">ChatGPT</span></div><h3>接收完整漫画</h3><p>ChatGPT 制作九张独立画格和封面，打包后由此导入。支持 ZIP（含常见压缩格式）或逐张图片导入。</p><p class="wf-meta">已导入画格：${p.panels.filter(x=>x.image).length}/9　|　独立封面：${p.cover?'已具备':'缺失'}</p><label class="button dark">导入 ChatGPT 交付包<input type="file" id="wfUpload" accept=".zip,application/zip,.png,.jpg,.jpeg,.webp,.pdf,.json" multiple hidden></label><a href="#/reader/${e(p.id)}" class="button">漫画预览 ↗</a><p class="wf-meta">导入前校验任务编号、图片签名、数量与大小；旧图片不会在校验失败时被覆盖。</p></section>
<section class="wf-step ${['delivered','workbuddy_ready','workbuddy_processing'].includes(wfPhase(p))?'active':''}"><div class="wf-stephead"><span class="wf-num">03</span><span class="chip">WorkBuddy</span></div><h3>交给公众号执行</h3><p>必须完成作者审核。生成包含九张漫画、封面、来源台账、文案和执行说明的 WorkBuddy 专用 ZIP。</p><p class="wf-meta">作者审核：${p.status==='已审核'||p.status==='已发布'?'已通过':'未通过'}　·　${p.checks.filter(Boolean).length}/6 项复核</p><button class="button dark" data-wf="publishpack">生成 WorkBuddy 发表包</button><button class="button" data-wf="mark-sent">记录已移交</button><a class="button" href="#/studio/${e(p.id)}/4">完成审核 ↗</a></section></div>`:'<div class="empty">请先建立一部作品。</div>')+
`<section class="box" style="margin-top:20px"><div class="sectionbar"><h2>交付与回执</h2><p>按实际完成情况记录，不自动假定发布成功</p></div><div class="wf-form"><div class="field"><label>WorkBuddy 微信公众号发表链接（真实发表后填写）</label><input id="wfReceipt" type="url" placeholder="https://mp.weixin.qq.com/s/..." value="${e(h.receipt||'')}"></div><button class="button" data-wf="receipt">记录发表回执</button></div><p class="minor">回执仅为人工录入，平台不具备微信账号直发或文章链接自动校验权限；正式上线状态需在公众号后台复核。</p></section>`+
`<section class="box" style="margin-top:20px"><h3>三方责任界面</h3><p class="wf-instructions"><strong>WORLD/TOON：</strong>发出明确且可复查的任务工单，不生图、不代替 ChatGPT。<br><strong>ChatGPT：</strong>完成漫画生产及完整的可下载交付包，不能以空文件或生成说明冒充成品。<br><strong>WorkBuddy：</strong>核验成品、进入公众号后台上传贴图，按授权的计划发表，并回传文章链接或后台结果。不依赖平台猜测发表结果。</p></section>`}
function wfInitTask(p){let h=p.handoff||{};if(!h.taskId||h.phase==='not_started'){h.taskId='WT-'+new Date().toISOString().replace(/\D/g,'').slice(0,14)+'-'+uid().slice(0,8);h.taskAt=now()}h.mode=wfMode(p);h.phase='task_ready';p.handoff=h;setChange(p,'生成 ChatGPT 制作任务');return h}
async function wfMakeTask(p){
 const missing=wfCanTask(p);if(missing.length)throw Error('请先补齐：'+missing.join('、'));
 wfInitTask(p);
 if(typeof wtArchiveKey==='function'){const key=await wtArchiveKey(p);p.handoff.taskId='WT-'+key.slice(0,20)}
 const task=wfTaskObject(p),prompt=wfPrompt(p);
 const files=[{name:'task.json',bytes:enc.encode(JSON.stringify(task,null,2))},{name:'ChatGPT_制作指令.md',bytes:enc.encode(prompt)},{name:'交接说明.txt',bytes:enc.encode('独立漫画仓库：chenzhe223-tech/worldtoon。任务只在 GitHub 真实写入成功后才算派单；本 ZIP 是离线备份。ChatGPT 负责九张实图+封面并提交 deliveries/<task_id>/；WorkBuddy 扫描验收队列，发表后将真实回执写入 receipts/<task_id>.json。')}];
 saveFile(packZip(files),'WORLD_TOON_ChatGPT任务_'+safeName(p.title)+'.zip');
 if(typeof wtArchivePushTask!=='function'){p.handoff.repoError='仓库派单接口未加载';setChange(p,'仅生成本地备份，尚未入仓');render();notify('任务 ZIP 已生成，但尚未派单入仓');return}
 try{const result=await wtArchivePushTask(p,task,prompt);p.handoff.repoError=null;setChange(p,'GitHub 工单写入已确认');render();notify(result.existing?'GitHub 仓库已存在同一任务（已去重）':'GitHub 漫画仓库正式派单成功')}
 catch(err){p.handoff.repoQueuedAt=null;p.handoff.repoError=String(err?.message||err);setChange(p,'GitHub 派单未成功，本地 ZIP 已保留');render();notify('尚未派单到 GitHub：'+p.handoff.repoError)}
}
async function wfCopyPrompt(p){const missing=wfCanTask(p);if(missing.length)throw Error('请先补齐：'+missing.join('、'));if(!wfGet(p).taskId)wfInitTask(p);await copyText(wfPrompt(p));render()}
const wfImgExt=f=>/\.(png|jpg|jpeg|webp)$/i.test(f),wfImageMime=n=>/\.png$/i.test(n)?'image/png':/\.webp$/i.test(n)?'image/webp':'image/jpeg';
function wfImageFile(name,bytes){let type=wfImageMime(name);if(bytes.length<16||bytes.length>12*1024*1024)throw Error('单张图片超出 12MB 或为空：'+name);let png=bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71;let jpg=bytes[0]===255&&bytes[1]===216&&bytes[2]===255;let webp=bytes[0]===82&&bytes[1]===73&&bytes[2]===70&&bytes[3]===70&&String.fromCharCode(...bytes.slice(8,12))==='WEBP';if(!(png&&type==='image/png'||jpg&&type==='image/jpeg'||webp&&type==='image/webp'))throw Error('图片格式与文件名不一致：'+name);return new Blob([bytes],{type})}
async function wfUnzip(file){const raw=new Uint8Array(await file.arrayBuffer());if(raw.length>180*1024*1024)throw Error('ZIP 超过 180MB 限制');let cd=-1;for(let i=raw.length-22;i>=Math.max(0,raw.length-65557);i--){if(raw[i]===80&&raw[i+1]===75&&raw[i+2]===5&&raw[i+3]===6){cd=i;break}}if(cd<0)throw Error('找不到 ZIP 中央目录');const view=new DataView(raw.buffer);let count=view.getUint16(cd+10,true),pos=view.getUint32(cd+16,true),seen=new Map(),total=0;if(count>40)throw Error('交付包文件数量超过 40');for(let i=0;i<count;i++){if(view.getUint32(pos,true)!==0x02014b50)throw Error('ZIP 索引无效');const flags=view.getUint16(pos+8,true),method=view.getUint16(pos+10,true),csize=view.getUint32(pos+20,true),usize=view.getUint32(pos+24,true),nlen=view.getUint16(pos+28,true),extra=view.getUint16(pos+30,true),comment=view.getUint16(pos+32,true),local=view.getUint32(pos+42,true),name=dec.decode(raw.slice(pos+46,pos+46+nlen));pos+=46+nlen+extra+comment;if(!name||name.endsWith('/'))continue;if(name.includes('..')||name.startsWith('/')||/^[A-Za-z]:/.test(name))throw Error('ZIP 包含非法路径');if(flags&1)throw Error('不支持加密 ZIP');if(![0,8].includes(method))throw Error('ZIP 使用了不支持的压缩方法');if(usize>22*1024*1024||csize>180*1024*1024)throw Error('ZIP 中包含超大文件');total+=usize;if(total>150*1024*1024)throw Error('ZIP 解压总量超过 150MB');if(view.getUint32(local,true)!==0x04034b50)throw Error('ZIP 条目损坏');const at=local+30+view.getUint16(local+26,true)+view.getUint16(local+28,true);if(at+csize>raw.length)throw Error('ZIP 内容越界');let bytes=raw.slice(at,at+csize);if(method===8){if(!('DecompressionStream'in window))throw Error('浏览器不支持 ZIP 解压；可改为逐张上传图片');try{const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('deflate-raw'));bytes=new Uint8Array(await new Response(stream).arrayBuffer())}catch{throw Error('压缩 ZIP 解压失败；可改为逐张上传 PNG/JPG 文件')}}if(bytes.length!==usize)throw Error('ZIP 条目大小不符：'+name);if(seen.has(name))throw Error('ZIP 文件重名：'+name);seen.set(name,bytes)}return seen}
function wfPanelIndex(name){let leaf=name.replace(/\\/g,'/').split('/').at(-1);const m=leaf.match(/^(?:panel[_-]?|frame[_-]?)?(0?[1-9])(?:[_-][^.]*)?\.(png|jpg|jpeg|webp)$/i);return m?Number(m[1])-1:-1}
async function wfImport(p,input){if(!wfGet(p).taskId)throw Error('请先生成平台制作任务，再导入与任务对应的作品');const incoming=[...input.files];if(!incoming.length)return;let files=new Map();if(incoming.length===1&&/\.zip$/i.test(incoming[0].name)){files=await wfUnzip(incoming[0])}else{for(const f of incoming){if(f.size>22*1024*1024)throw Error('单个文件超过 22MB：'+f.name);if(files.has(f.name))throw Error('文件名重复：'+f.name);files.set(f.name,new Uint8Array(await f.arrayBuffer()))}}const imgs=Array(9).fill(null);let cover=null,pdf=null,meta=null;for(const [name,bytes] of files){const leaf=name.replace(/\\/g,'/').split('/').at(-1);if(/^delivery\.json$/i.test(leaf)){meta=JSON.parse(dec.decode(bytes));continue}if(/^comic\.pdf$/i.test(leaf)){if(bytes.length>22*1024*1024||dec.decode(bytes.slice(0,4))!=='%PDF')throw Error('PDF 无效或超出 22MB');pdf=new Blob([bytes],{type:'application/pdf'});continue}if(/^cover\.(png|jpg|jpeg|webp)$/i.test(leaf)){cover=wfImageFile(leaf,bytes);continue}const k=wfPanelIndex(name);if(k>=0){if(imgs[k])throw Error('出现重复漫画页：第'+(k+1)+'格');imgs[k]=wfImageFile(leaf,bytes)}}if(imgs.some(x=>!x))throw Error('九张独立漫画图片不完整：缺少 '+imgs.map((x,i)=>x?'':String(i+1).padStart(2,'0')).filter(Boolean).join('、'));if(!cover)throw Error('缺少独立封面 cover.png/JPG/WebP');if(meta){if(meta.task_id&&meta.task_id!==p.handoff.taskId)throw Error('交付包任务编号与当前作品不一致');if(meta.panel_count!=null&&Number(meta.panel_count)!==9)throw Error('交付包的画格数量说明不是 9');if(meta.title&&meta.title!==p.title)throw Error('交付包标题与当前作品不一致')}let ids=[];try{for(let i=0;i<9;i++){const k=uid();await putMedia(k,imgs[i]);ids.push(k)}const ckey=uid();await putMedia(ckey,cover);ids.push(ckey);let pdfkey='';if(pdf){pdfkey=uid();await putMedia(pdfkey,pdf);ids.push(pdfkey)}p.panels.forEach((x,i)=>{x.image='media:'+ids[i]});p.cover='media:'+ckey;p.handoff={...p.handoff,phase:'delivered',deliveryAt:now(),deliveryManifest:meta||null,pdf:pdfkey?'media:'+pdfkey:null,receipt:null};p.status='草稿';p.reviewedAt=null;p.checks=Array(6).fill(false);setChange(p,'接收 ChatGPT 九格漫画及封面，待人工复核');render();notify('九张漫画及封面导入成功；请人工复核后移交')}catch(err){for(const id of ids)await delMedia(id).catch(()=>{});throw err}}
async function wfWorkBuddy(p){if(!p.handoff?.taskId)throw Error('尚未建立任务编号');if(p.panels.filter(x=>x.image).length!==9||!p.cover)throw Error('必须具备九张完整漫画和独立封面');if(!['已审核','已发布'].includes(p.status)||canApprove(p).length)throw Error('请先在创作工作台完成全部 6 项人工核查并审核通过：'+canApprove(p).join('、'));const entries=[];for(let i=0;i<9;i++){let blob=await getImageBlob(p.panels[i].image);entries.push({name:'panels/'+String(i+1).padStart(2,'0')+'.'+contentExt(blob),bytes:await blobBytes(blob)})}let cover=await getImageBlob(p.cover);entries.push({name:'cover.'+contentExt(cover),bytes:await blobBytes(cover)});if(p.handoff.pdf){let pdf=await getMedia(p.handoff.pdf.slice(6));if(pdf)entries.push({name:'comic.pdf',bytes:await blobBytes(pdf)})}const caption=`《${p.title}》\n${p.subtitle||p.description||''}\n\n${p.disclosure}\n\nWORLD/TOON · By DAVYLAB`;const manifest={schema:'davylab.worldtoon.workbuddy.v1',task_id:p.handoff.taskId,from:'ChatGPT delivery reviewed by creator',to:'WorkBuddy',channel:'微信公众号',post_type:'贴图',title:p.title,images:entries.filter(x=>x.name.startsWith('panels/')).map(x=>x.name),cover:entries.find(x=>x.name.startsWith('cover.'))?.name,caption:'weixin-caption.txt',disclaimer:p.disclosure,source_urls:validSources(p),reviewed_at:p.reviewedAt,approved_for_publication:true,actual_published:false,require_receipt:true};entries.push({name:'workbuddy-publish.json',bytes:enc.encode(JSON.stringify(manifest,null,2))},{name:'weixin-caption.txt',bytes:enc.encode(caption)},{name:'source-ledger.json',bytes:enc.encode(JSON.stringify({sourceURLs:validSources(p),factNotes:p.factNotes,fiction:p.fiction},null,2))},{name:'WORKBUDDY执行说明.md',bytes:enc.encode(`# WORLD/TOON 公众号贴图发布工单\n\n任务：${p.handoff.taskId}\n作品：《${p.title}》\n\n请按 01–09 顺序上传九张漫画，使用 cover 文件作为封面，使用 weixin-caption.txt 为文案基础。\n确认原创虚构免责声明可见；按授权排期完成微信公众号贴图发表，遵守平台规范和素材使用权。\n请在实际发布完成后回传文章 URL、发表时间和成功证据；仅上传或保存草稿不算已发表。\n不得在没有审校批准或图片缺失的情况下直接发布。\n`) });saveFile(packZip(entries),'WORLD_TOON_WorkBuddy发表包_'+safeName(p.title)+'.zip');p.handoff={...p.handoff,phase:'workbuddy_ready',packageAt:now()};setChange(p,'导出 WorkBuddy 已审校发表包（尚未移交）');render();notify('WorkBuddy 发表包已下载；请实际移交给 WorkBuddy')}
async function wfClick(ev){const b=ev.target.closest('[data-wf]');if(!b||wfBusy)return;ev.preventDefault();ev.stopPropagation();const p=selected();if(!p){notify('请先选择作品');return}wfBusy=true;try{switch(b.dataset.wf){case'task':await wfMakeTask(p);break;case'copy':await wfCopyPrompt(p);break;case'publishpack':await wfWorkBuddy(p);break;case'mark-sent':if(wfPhase(p)!=='workbuddy_ready')throw Error('请先导出已审校的 WorkBuddy 发表包');if(!confirm('确认你已经把 ZIP 文件实际交给 WorkBuddy？'))break;p.handoff.phase='workbuddy_processing';p.handoff.sentAt=now();setChange(p,'人工确认已移交 WorkBuddy');render();break;case'receipt':{let raw=document.querySelector('#wfReceipt')?.value?.trim()||'',u;try{u=new URL(raw)}catch{throw Error('请填写实际发表的微信公众号文章链接')}if(u.protocol!=='https:'||u.hostname!=='mp.weixin.qq.com'||!/^\/s(?:\/|$)/.test(u.pathname))throw Error('需要微信公众号正式文章链接（mp.weixin.qq.com/s/...）');if(!['workbuddy_ready','workbuddy_processing','publish_reported'].includes(wfPhase(p)))throw Error('请先生成 WorkBuddy 发表包');p.handoff.receipt=u.href;p.handoff.receiptAt=now();p.handoff.phase='publish_reported';setChange(p,'人工录入公众号发表回执（尚未自动核验）');render();notify('已记录链接；仍需到公众号后台核验实际发表');break}}}catch(err){notify(err.message||String(err))}finally{wfBusy=false}}
function wfChange(ev){const x=ev.target,p=selected();if(x.id==='wfProject'){ui.selected=x.value;render();return}if(!p)return;if(x.id==='wfMode'){if(p.handoff?.taskId){notify('任务已建立：要更改类型请建立新作品，避免任务与交付不一致');render();return}p.handoff={...p.handoff,mode:x.value};setChange(p,'修改作品类型');render();return}if(x.id==='wfUpload'){wfImport(p,x).catch(err=>notify('交付包导入失败：'+err.message));}}
// Layout styles are now provided by styles.css (CSP safe).
document.addEventListener('click',wfClick);
document.addEventListener('change',wfChange);

